{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C51"],
      "claim": "KNI-272, a very close structural analogue (transfer 0.9653), had absolute oral bioavailability of 36.40% when given as a capsule post-prandially in patients, directly supporting F ≥20% under fed conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "KNI-272 absolute bioavailability was 54.97 ± 19.78% after a 10 mg/kg oral capsule in fasting patients, confirming high oral bioavailability across adult doses.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "KNI-272 capsule bioavailability ranged from approximately 22% to 55% and was not appreciably different between fasting and post-prandial states, supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Atazanavir, a related peptidomimetic HIV protease inhibitor with high transferability (0.9601), has absolute oral bioavailability of 68% (57–80%) in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Atazanavir oral bioavailability is >90% when taken with food, providing direct fed-state support for high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "A pediatric study of KNI-272 with Ora-Plus reported mean absolute bioavailability of 12% (range 3.5–25%), a contradictory low observation, but it is pediatric/formulation-specific and the range overlaps the 20% threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The closest analogue KNI-272 (transfer 0.9653) shows adult absolute oral bioavailability of approximately 30–55%, including 36.4% post-prandially and 22–55% overall independent of food. Related peptidomimetic atazanavir shows 68% fasting and >90% with food. These direct human data strongly support F ≥20% for the query, especially under fed conditions. A single pediatric low-F observation is outweighed by consistent adult and fed-state measurements.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the exact query molecule; reliance on close analogues.",
    "The pediatric low-F observation for KNI-272 raises uncertainty about age- and formulation-dependent absorption.",
    "The specific effects of the query's S-benzyl and decahydroisoquinoline modifications on absorption and first-pass metabolism are not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

